Here’s a simple, single-file app for recording patients and visit notes. It stores data **only in the browser on the current device**.

Save this as `physio-notes.html`, then open it in a browser.

> **Privacy:** This is a basic prototype, not a secure medical-record system. Browser storage is not encrypted or backed up, and anyone with access to the browser may be able to read the notes. Check applicable privacy requirements before using real patient information.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Physio Visit Notes</title>
  <style>
    * { box-sizing: border-box; }
    body {
      margin: 0;
      font: 16px/1.5 system-ui, sans-serif;
      color: #173036;
      background: #f2f7f6;
    }
    header {
      padding: 20px;
      background: #176b68;
      color: white;
    }
    header h1 { margin: 0; font-size: 1.5rem; }
    header p { margin: 4px 0 0; }
    main {
      max-width: 1100px;
      margin: 24px auto;
      padding: 0 16px;
      display: grid;
      grid-template-columns: 300px 1fr;
      gap: 20px;
    }
    .panel {
      background: white;
      border: 1px solid #dbe8e6;
      border-radius: 10px;
      padding: 20px;
    }
    h2, h3 { margin-top: 0; }
    label { display: block; font-weight: 600; margin: 12px 0 4px; }
    input, textarea, button {
      font: inherit;
      border-radius: 6px;
    }
    input, textarea {
      width: 100%;
      padding: 9px;
      border: 1px solid #aabfbc;
    }
    textarea { min-height: 110px; resize: vertical; }
    button {
      border: 0;
      padding: 9px 13px;
      background: #176b68;
      color: white;
      cursor: pointer;
    }
    button:hover { background: #105451; }
    button.secondary { background: #e7f0ef; color: #173036; }
    button.danger { background: #a53636; }
    .patient-list { display: grid; gap: 6px; margin-top: 16px; }
    .patient-list button { text-align: left; overflow-wrap: anywhere; }
    .patient-list button.selected { outline: 2px solid #176b68; }
    .row { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
    .row.spread { justify-content: space-between; }
    .visit {
      border-top: 1px solid #dbe8e6;
      padding-top: 16px;
      margin-top: 16px;
    }
    .visit p { white-space: pre-wrap; overflow-wrap: anywhere; }
    .muted { color: #536d69; }
    .notice { font-size: .9rem; }
    @media (max-width: 700px) {
      main { grid-template-columns: 1fr; }
    }
  </style>
</head>
<body>
  <header>
    <h1>Physio Visit Notes</h1>
    <p>Simple patient and visit records</p>
  </header>

  <main>
    <aside class="panel">
      <h2>Patients</h2>
      <form id="patient-form">
        <label for="patient-name">Patient name</label>
        <input id="patient-name" required maxlength="120" autocomplete="off">
        <div style="margin-top: 10px">
          <button type="submit">Add patient</button>
        </div>
      </form>

      <div id="patient-list" class="patient-list"></div>
      <hr>
      <button id="export" class="secondary" type="button">Export all data</button>
      <p class="muted notice">
        Data stays in this browser. Exported files contain patient information.
      </p>
    </aside>

    <section class="panel">
      <div id="empty" class="muted">Add or select a patient to get started.</div>
      <div id="patient-view" hidden>
        <div class="row spread">
          <h2 id="selected-name"></h2>
          <button id="delete-patient" class="danger" type="button">Delete patient</button>
        </div>

        <h3>Add a visit</h3>
        <form id="visit-form">
          <label for="visit-date">Date</label>
          <input id="visit-date" type="date" required>

          <label for="visit-notes">Notes</label>
          <textarea id="visit-notes" required
            placeholder="Assessment, treatment, progress and plan"></textarea>

          <div style="margin-top: 10px">
            <button type="submit">Save visit</button>
          </div>
        </form>

        <h3 style="margin-top: 28px">Visit history</h3>
        <div id="visits"></div>
      </div>
    </section>
  </main>

  <script>
    const KEY = "physio-notes-v1";
    const $ = id => document.getElementById(id);
    let patients = [];
    let selectedId = null;

    try {
      const saved = JSON.parse(localStorage.getItem(KEY) || "[]");
      if (Array.isArray(saved)) patients = saved;
    } catch (error) {
      alert("Could not read saved data. Check your browser storage before continuing.");
    }

    function save() {
      try {
        localStorage.setItem(KEY, JSON.stringify(patients));
        return true;
      } catch (error) {
        alert("Could not save. Browser storage may be full or unavailable.");
        return false;
      }
    }

    function today() {
      const d = new Date();
      return [
        d.getFullYear(),
        String(d.getMonth() + 1).padStart(2, "0"),
        String(d.getDate()).padStart(2, "0")
      ].join("-");
    }

    function render() {
      const list = $("patient-list");
      list.replaceChildren();

      patients.forEach(patient => {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "secondary" + (patient.id === selectedId ? " selected" : "");
        button.textContent = patient.name;
        button.onclick = () => {
          selectedId = patient.id;
          $("visit-form").reset();
          $("visit-date").value = today();
          render();
        };
        list.appendChild(button);
      });

      const patient = patients.find(p => p.id === selectedId);
      $("empty").hidden = !!patient;
      $("patient-view").hidden = !patient;
      if (!patient) return;

      $("selected-name").textContent = patient.name;
      const visits = $("visits");
      visits.replaceChildren();

      if (!patient.visits.length) {
        visits.textContent = "No visits recorded yet.";
        return;
      }

      [...patient.visits]
        .sort((a, b) => b.date.localeCompare(a.date))
        .forEach(visit => {
          const article = document.createElement("article");
          article.className = "visit";

          const heading = document.createElement("strong");
          heading.textContent = visit.date;
          const notes = document.createElement("p");
          notes.textContent = visit.notes;
          const remove = document.createElement("button");
          remove.type = "button";
          remove.className = "secondary";
          remove.textContent = "Delete visit";
          remove.onclick = () => {
            if (!confirm("Delete this visit note?")) return;
            const oldVisits = patient.visits;
            patient.visits = patient.visits.filter(v => v.id !== visit.id);
            if (!save()) patient.visits = oldVisits;
            render();
          };

          article.append(heading, notes, remove);
          visits.appendChild(article);
        });
    }

    $("patient-form").onsubmit = event => {
      event.preventDefault();
      const name = $("patient-name").value.trim();
      if (!name) return;

      const patient = { id: crypto.randomUUID(), name, visits: [] };
      patients.push(patient);
      if (!save()) {
        patients.pop();
        return;
      }
      selectedId = patient.id;
      $("patient-form").reset();
      $("visit-form").reset();
      $("visit-date").value = today();
      render();
    };

    $("visit-form").onsubmit = event => {
      event.preventDefault();
      const patient = patients.find(p => p.id === selectedId);
      const notes = $("visit-notes").value.trim();
      const date = $("visit-date").value;
      if (!patient || !date || !notes) return;

      patient.visits.push({ id: crypto.randomUUID(), date, notes });
      if (!save()) {
        patient.visits.pop();
        return;
      }
      $("visit-form").reset();
      $("visit-date").value = today();
      render();
    };

    $("delete-patient").onclick = () => {
      const patient = patients.find(p => p.id === selectedId);
      if (!patient || !confirm(`Delete ${patient.name} and all their visits?`)) return;
      const oldPatients = patients;
      patients = patients.filter(p => p.id !== selectedId);
      if (!save()) {
        patients = oldPatients;
        return;
      }
      selectedId = null;
      render();
    };

    $("export").onclick = () => {
      const blob = new Blob([JSON.stringify(patients, null, 2)], {
        type: "application/json"
      });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `physio-notes-${today()}.json`;
      link.click();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    };

    $("visit-date").value = today();
    render();
  </script>
</body>
</html>
```

The export button downloads a JSON copy; this version doesn’t yet support importing it back into the app. Clearing browser data can also delete the stored records.

